// ==UserScript==
// @name        真实世界·状态栏桥接
// @version     1.8.0
// @description 嵌入状态栏HTML，通过MutationObserver注入iframe
// @author      RealWorld Project
// ==/UserScript==

(function() {
  'use strict';

  var NAME = '[RealWorld SB-Bridge]';
  var SB_HTML_B64 = '';
  var MOUNT_SELECTOR = '.rw-sb-mount';

  function decodeHTML() {
    var bytes = Uint8Array.from(atob(SB_HTML_B64), function(c) { return c.charCodeAt(0); });
    return new TextDecoder('utf-8').decode(bytes);
  }

  function createIframe() {
    var html = decodeHTML();
    var blob = new Blob([html], { type: 'text/html' });
    var url = URL.createObjectURL(blob);
    var iframe = document.createElement('iframe');
    iframe.src = url;
    iframe.style.cssText = 'width:100%;border:none;overflow:hidden;min-height:300px';
    iframe.scrolling = 'no';
    iframe.onload = function() {
      try {
        var body = iframe.contentWindow.document.body;
        var h = body.scrollHeight;
        if (h > 50) iframe.style.height = h + 'px';
        // ResizeObserver for dynamic content
        if (iframe.contentWindow.ResizeObserver) {
          var ro = new iframe.contentWindow.ResizeObserver(function() {
            iframe.style.height = body.scrollHeight + 'px';
          });
          ro.observe(body);
        }
      } catch(e) {}
    };
    return iframe;
  }

  function getStatData() {
    try {
      if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
        var data = Mvu.getMvuData({ type: 'chat' });
        if (data && data.stat_data) return data.stat_data;
      }
    } catch(e) {}
    try {
      if (typeof getVariables === 'function') {
        var v = getVariables({ type: 'chat' });
        if (v && v.stat_data) return v.stat_data;
        return v;
      }
    } catch(e) {}
    return null;
  }

  function pushToIframes() {
    var sd = getStatData();
    if (!sd) return;
    var iframes = document.querySelectorAll('iframe[src^="blob:"]');
    for (var i = 0; i < iframes.length; i++) {
      try {
        var cw = iframes[i].contentWindow;
        if (cw) cw.postMessage({ type: 'sb-data', stat_data: sd }, '*');
      } catch(e) {}
    }
  }

  function mountOne(el) {
    if (el.hasAttribute('data-rw-mounted')) return;
    el.setAttribute('data-rw-mounted', '1');
    var iframe = createIframe();
    el.parentNode.replaceChild(iframe, el);
  }

  function scanAndMount() {
    var list = document.querySelectorAll(MOUNT_SELECTOR);
    for (var i = 0; i < list.length; i++) {
      mountOne(list[i]);
    }
  }

  function init() {
    // MutationObserver: watch for new mount points
    var mo = new MutationObserver(function(mutations) {
      var found = false;
      for (var i = 0; i < mutations.length; i++) {
        var added = mutations[i].addedNodes;
        for (var j = 0; j < added.length; j++) {
          var node = added[j];
          if (node.nodeType === 1) {
            if (node.matches && node.matches(MOUNT_SELECTOR)) {
              mountOne(node);
            }
            // Check children too
            if (node.querySelectorAll) {
              var children = node.querySelectorAll(MOUNT_SELECTOR);
              for (var k = 0; k < children.length; k++) {
                mountOne(children[k]);
              }
            }
          }
        }
      }
    });
    mo.observe(document.body, { childList: true, subtree: true });

    // Scan existing mounts
    setTimeout(scanAndMount, 500);

    // Listen for MVU updates → push data to iframes
    if (typeof Mvu !== 'undefined') {
      try {
        Mvu.on('mag_variable_initiailized', function() {
          setTimeout(pushToIframes, 1500);
        });
        Mvu.on('mag_variable_update_ended', function() {
          setTimeout(pushToIframes, 500);
        });
        console.log(NAME, 'Bridge active (MVU events)');
        // Initial push
        setTimeout(pushToIframes, 3000);
      } catch(e) {}
    } else if (typeof waitGlobalInitialized === 'function') {
      waitGlobalInitialized('Mvu').then(function() {
        Mvu.on('mag_variable_initiailized', function() {
          setTimeout(pushToIframes, 1500);
        });
        Mvu.on('mag_variable_update_ended', function() {
          setTimeout(pushToIframes, 500);
        });
        console.log(NAME, 'Bridge active (deferred)');
        setTimeout(pushToIframes, 3000);
      }).catch(function() {
        console.warn(NAME, 'Mvu not available, polling');
        setInterval(pushToIframes, 5000);
      });
    } else {
      setInterval(pushToIframes, 5000);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { setTimeout(init, 500); });
  } else {
    init();
  }
})();
